So let’s prepare the data:


Code
data_list = list(N = nrow(nets),
                 net      = nets$net,
                 net_real = as.numeric(nets$net),
                 X = cbind(nets$income, nets$temperature, nets$health),
                 malaria_risk = nets$malaria_risk)


and run it through the Stan model below. It looks like a lot, but it’s really just a lightly adapted form of the same brms starting points as the original posts. The new addition here is the transformed parameters block:
data {
  int&lt;lower=0&gt; N;
  array[N] int  net;
  vector[N] net_real;
  matrix[N,3] X;
  vector[N] malaria_risk;
}

transformed data {
  real mx;
  vector[N] cent_net;
  int Kc = 3;
  matrix[N, Kc] Xc;  // centered version of X without an intercept
  vector[Kc] means_X;  // column means of X before centering
  matrix[N, Kc] XQ;
  matrix[Kc, Kc] XR;
  matrix[Kc, Kc] XR_inv;

  mx = mean(net_real);
  cent_net = net_real - mx;

  for (i in 1:3) {
    means_X[i] = mean(X[, i]);
    Xc[, i] = X[, i] - means_X[i];
  }
  // compute and scale QR decomposition
  XQ = qr_thin_Q(Xc) * sqrt(N - 1);
  XR = qr_thin_R(Xc) / sqrt(N - 1);
  XR_inv = inverse(XR);
}
parameters {
  // parameters for the treatment model
  real tr_intercept_cent; // treatment intercept for centered X
  vector[Kc] tr_coef_qr; // treatment coefs on QR scale

  // parameters for the outcome model
  real oc_intercept; // intercept of malaria_risk ~ net
  real oc_coef; // coef of malaria_risk ~ net
  real&lt;lower=0&gt; sigma;
}

transformed parameters {
  vector[Kc] tr_coef = XR_inv * tr_coef_qr;
  vector[N] prop_scores;
  vector[N] weights;

  prop_scores = inv_logit(X * tr_coef + tr_intercept_cent);
  weights = net_real ./ prop_scores + (1-net_real) ./ (1-prop_scores);
}
model {
  // likelihood for the treatment model
  target += bernoulli_logit_glm_lpmf(net | XQ, tr_intercept_cent, tr_coef_qr);

  // likelihood for the outcome model
  for (n in 1:N) {
      target += weights[n] * normal_lpdf(malaria_risk[n] | oc_coef * cent_net[n] + oc_intercept, sigma);
  }

  // priors for the outcome model
  target += normal_lpdf(oc_coef | 0, 10);
  target += student_t_lpdf(oc_intercept | 3, 0, 5);
  target += student_t_lpdf(sigma | 3, 0, 14.8)
              - 1 * student_t_lccdf(0 | 3, 0, 14.8);

  // priors for the treatment model
  target += student_t_lpdf(tr_intercept_cent | 3, 0, 2.5);
  target += normal_lpdf(tr_coef_qr | 0, 3);
}

generated quantities {
  real tr_intercept_id = tr_intercept_cent - dot_product(means_X, tr_coef);

}
Let’s run it and see what we get:


